export function validateInvoiceLines(lines: {
    description: string;
    quantity: number;
    unitCents: number;
}[]) {
    const errors = [];
    lines.forEach((line, i) => {
        if (typeof line.description !== 'string' || !line.description.trim())
            errors.push('line ' + i + ': description');
        if (!Number.isSafeInteger(line.quantity) || line.quantity <= 0)
            errors.push('line ' + i + ': quantity');
        if (!Number.isSafeInteger(line.unitCents) || line.unitCents < 0)
            errors.push('line ' + i + ': price');
    });
    return { valid: errors.length === 0, errors };
}
